/// Impl-targeted harness for `initialize_config`. Kani's automatic
/// overflow / underflow / UB checks run on every path through the
/// real handler. `#[kani::unwind(34)]` bounds Pinocchio's 32-byte
/// pubkey/account comparisons plus generated valid-path loops.
/// Proof profile notes:
/// - source account order: payer, config, system_program
/// - ABI/dispatcher tag: 0
/// - PDA derivations: config -> config (found)
/// - token owner/mint projections: none inferred
#[kani::proof]
#[kani::unwind(34)]
fn verify_initialize_config_impl() {
    let program_id: [u8; 32] = [42u8; 32];
    let authority_key: [u8; 32] = [7u8; 32];
    let max_fee_bps: u16 = kani::any(); // spec type: U128
    let lane_count: u8 = kani::any(); // spec type: U64
    kani::assume(max_fee_bps <= 10000);
    kani::assume(lane_count > 0);
    kani::assume((max_fee_bps as u128) <= u16::MAX as u128);
    kani::assume((lane_count as u64) <= u8::MAX as u64);

    let config_key = crate::derive_config(&program_id).0;
    let mut payer = build_minimal_account(authority_key, true, true);
    // ABI account layout `config_account`: 621 byte data region.
    let mut config_data: [u8; 621] = [0u8; 621];
    config_data[0] = 76u8;
    config_data[1] = 72u8;
    config_data[2] = 85u8;
    config_data[3] = 66u8;
    config_data[4] = 67u8;
    config_data[5] = 70u8;
    config_data[6] = 71u8;
    config_data[7] = 51u8;
    let mut config = build_data_account(config_key, program_id, false, true, config_data);
    write_state_pubkey(&mut config, 8, [4u8; 32]);
    write_state_pubkey(&mut config, 40, [5u8; 32]);
    write_state_pubkey(&mut config, 72, [6u8; 32]);
    write_state_u16(&mut config, 104, (max_fee_bps as u16));
    write_state_bool(&mut config, 106, false);
    write_state_u8(&mut config, 107, (lane_count as u8));
    write_state_u8(&mut config, 108, (2 as u8));
    write_state_u8(&mut config, 108, (2 as u8));
    write_state_pubkey(&mut config, 109, [7u8; 32]);
    write_state_pubkey(&mut config, 141, [8u8; 32]);
    let mut system_program = build_minimal_account([3u8; 32], false, false);
    let mut admin = build_minimal_account([4u8; 32], false, false);
    let mut hub_authorizer = build_minimal_account([5u8; 32], false, false);
    let mut inventory_rebalancer = build_minimal_account([6u8; 32], false, false);
    let mut allowed_mint_0 = build_minimal_account([7u8; 32], false, false);
    let mut allowed_mint_1 = build_minimal_account([8u8; 32], false, false);

    let accounts: [ManuallyDrop<AccountInfo>; 8] = unsafe {
        [
            ManuallyDrop::new(account_info_from_stack(&mut payer)),
            ManuallyDrop::new(account_info_from_stack(&mut config)),
            ManuallyDrop::new(account_info_from_stack(&mut system_program)),
            ManuallyDrop::new(account_info_from_stack(&mut admin)),
            ManuallyDrop::new(account_info_from_stack(&mut hub_authorizer)),
            ManuallyDrop::new(account_info_from_stack(&mut inventory_rebalancer)),
            ManuallyDrop::new(account_info_from_stack(&mut allowed_mint_0)),
            ManuallyDrop::new(account_info_from_stack(&mut allowed_mint_1)),
        ]
    };
    let accounts_slice: &[AccountInfo] =
        unsafe { core::slice::from_raw_parts(&accounts as *const _ as *const AccountInfo, 8) };

    let instruction_tag: u8 = 0u8;
    let mut instruction_data = [0u8; 101];
    instruction_data[0] = instruction_tag;
    // Profile note: source references param `admin` absent from the spec handler
    // Profile note: source references param `hub_authorizer` absent from the spec handler
    // Profile note: source references param `inventory_rebalancer` absent from the spec handler
    let generated_instruction_data_97_bytes = (max_fee_bps as u16).to_le_bytes();
    instruction_data[97] = generated_instruction_data_97_bytes[0];
    instruction_data[98] = generated_instruction_data_97_bytes[1];
    // Profile note: source references param `paused` absent from the spec handler
    instruction_data[100] = (lane_count as u8) as u8;

    // Pre-state snapshots for ABI-backed account assertions.
    let pre_state_config_admin = read_state_pubkey(&config, 8);
    let pre_state_config_hub_authorizer = read_state_pubkey(&config, 40);
    let pre_state_config_inventory_rebalancer = read_state_pubkey(&config, 72);
    let pre_state_config_max_fee_bps = read_state_u16(&config, 104);
    let pre_state_config_lane_count = read_state_u8(&config, 107);
    let pre_state_config_paused = read_state_bool(&config, 106);

    // Call the user's real dispatcher. Kani's automatic checks
    // (overflow / underflow / pointer UB) verify this path.
    let _result = crate::process_instruction(&program_id, accounts_slice, &instruction_data);
    kani::cover!(
        _result.is_ok(),
        "impl success path reachable under generated profile"
    );
    assert!(
        _result.is_ok(),
        "generated valid ABI/profile witness should reach success"
    );

    if _result.is_ok() {
        assert_eq!(read_state_pubkey(&config, 8), admin.hdr.key);
        assert_eq!(read_state_pubkey(&config, 40), hub_authorizer.hdr.key);
        assert_eq!(read_state_pubkey(&config, 72), inventory_rebalancer.hdr.key);
        assert_eq!(read_state_u16(&config, 104), (max_fee_bps as u16));
        assert_eq!(read_state_u8(&config, 107), (lane_count as u8));
        assert_eq!(read_state_bool(&config, 106), (0 != 0));
    }
}

