/// real handler. `#[kani::unwind(34)]` bounds Pinocchio's 32-byte
/// pubkey/account comparisons plus generated valid-path loops.
/// Proof profile notes:
/// - source account order: config, inventory_rebalancer, token_program, mint
/// - ABI/dispatcher tag: 5
/// - PDA derivations: config -> config (found); source_inventory -> inventory_account (found); destination_inventory -> inventory_account (found)
/// - token owner/mint projections: source_inventory mint=mint owner=source_authority owner_pda=missing; destination_inventory mint=mint owner=missing owner_pda=missing
#[kani::proof]
#[kani::unwind(34)]
fn verify_rebalance_inventory_impl() {
    let program_id: [u8; 32] = [42u8; 32];
    let authority_key: [u8; 32] = [7u8; 32];
    let amount: u32 = kani::any(); // spec type: U64
    let from_lane_id: u8 = kani::any(); // spec type: U64
    kani::assume(from_lane_id < 2);
    let to_lane_id: u8 = kani::any(); // spec type: U64
    kani::assume(to_lane_id < 2);
    kani::assume(amount > 0);
    kani::assume(amount <= 1000000);
    kani::assume(from_lane_id != to_lane_id);
    kani::assume((from_lane_id as u64) <= u8::MAX as u64);
    kani::assume((to_lane_id as u64) <= u8::MAX as u64);
    kani::assume((amount as u64) <= u64::MAX as u64);

    let config_key = crate::derive_config(&program_id).0;
    let source_inventory_hub_authority_key =
        crate::derive_hub_authority(&program_id, from_lane_id as u8).0;
    let source_authority_key = source_inventory_hub_authority_key;
    let source_inventory_key =
        crate::derive_inventory_account(&program_id, &[4u8; 32], from_lane_id as u8);
    let destination_inventory_hub_authority_key =
        crate::derive_hub_authority(&program_id, to_lane_id as u8).0;
    let destination_inventory_key =
        crate::derive_inventory_account(&program_id, &[4u8; 32], to_lane_id as u8);
    // ABI account layout `config_account`: 621 byte data region.
    let mut config_data: [u8; 621] = [0u8; 621];
    config_data[0] = 76u8;
    config_data[1] = 72u8;
    config_data[2] = 85u8;
    config_data[3] = 66u8;
    config_data[4] = 67u8;
    config_data[5] = 70u8;
    config_data[6] = 71u8;
    config_data[7] = 51u8;
    let mut config = build_data_account(config_key, program_id, false, false, config_data);
    write_state_pubkey(&mut config, 72, authority_key);
    write_state_u16(&mut config, 104, (10000 as u16));
    write_state_bool(&mut config, 106, false);
    write_state_u8(&mut config, 107, (2 as u8));
    write_state_u8(&mut config, 108, (2 as u8));
    write_state_u8(&mut config, 108, (1 as u8));
    write_state_pubkey(&mut config, 109, [4u8; 32]);
    let mut inventory_rebalancer = build_minimal_account(authority_key, true, false);
    let mut token_program = build_minimal_account(SPL_TOKEN_PROGRAM_ID, false, false);
    let mut mint = build_mint_account([4u8; 32], false, false, 6u8);
    let mut source_authority = build_minimal_account(source_authority_key, false, false);
    let mut source_inventory = build_token_account(
        source_inventory_key,
        true,
        false,
        [4u8; 32],
        source_authority_key,
        (amount as u64),
    );
    let mut destination_inventory = build_token_account(
        destination_inventory_key,
        true,
        false,
        [4u8; 32],
        destination_inventory_hub_authority_key,
        (0 as u64),
    );

    let accounts: [ManuallyDrop<AccountInfo>; 7] = unsafe {
        [
            ManuallyDrop::new(account_info_from_stack(&mut config)),
            ManuallyDrop::new(account_info_from_stack(&mut inventory_rebalancer)),
            ManuallyDrop::new(account_info_from_stack(&mut token_program)),
            ManuallyDrop::new(account_info_from_stack(&mut mint)),
            ManuallyDrop::new(account_info_from_stack(&mut source_authority)),
            ManuallyDrop::new(account_info_from_stack(&mut source_inventory)),
            ManuallyDrop::new(account_info_from_stack(&mut destination_inventory)),
        ]
    };
    let accounts_slice: &[AccountInfo] =
        unsafe { core::slice::from_raw_parts(&accounts as *const _ as *const AccountInfo, 7) };

    let instruction_tag: u8 = 5u8;
    let mut instruction_data = [0u8; 12];
    instruction_data[0] = instruction_tag;
    instruction_data[1] = 1u8;
    instruction_data[2] = (from_lane_id as u8) as u8;
    instruction_data[3] = (to_lane_id as u8) as u8;
    let generated_instruction_data_4_bytes = (amount as u64).to_le_bytes();
    instruction_data[4] = generated_instruction_data_4_bytes[0];
    instruction_data[5] = generated_instruction_data_4_bytes[1];
    instruction_data[6] = generated_instruction_data_4_bytes[2];
    instruction_data[7] = generated_instruction_data_4_bytes[3];
    instruction_data[8] = generated_instruction_data_4_bytes[4];
    instruction_data[9] = generated_instruction_data_4_bytes[5];
    instruction_data[10] = generated_instruction_data_4_bytes[6];
    instruction_data[11] = generated_instruction_data_4_bytes[7];

    // Pre-state snapshots for ABI-backed account assertions.
    let pre_state_config_admin = read_state_pubkey(&config, 8);
    let pre_state_config_max_fee_bps = read_state_u16(&config, 104);
    let pre_state_config_lane_count = read_state_u8(&config, 107);

    // Pre-token snapshots for generated Token.transfer assertions.
    let pre_transfer_0_from = read_token_amount(&source_inventory);
    let pre_transfer_0_to = read_token_amount(&destination_inventory);
    kani::assume(pre_transfer_0_from >= (amount as u64));
    kani::assume(pre_transfer_0_to <= u64::MAX - (amount as u64));

    // Call the user's real dispatcher. Kani's automatic checks
    // (overflow / underflow / pointer UB) verify this path.
    let _result = crate::process_instruction(&program_id, accounts_slice, &instruction_data);
    kani::cover!(
        _result.is_ok(),
        "impl success path reachable under generated profile"
    );
    assert!(
        _result.is_ok(),
        "generated valid ABI/profile witness should reach success"
    );

    if _result.is_ok() {
        assert_eq!(read_state_pubkey(&config, 8), pre_state_config_admin);
        assert_eq!(read_state_u16(&config, 104), pre_state_config_max_fee_bps);
        assert_eq!(read_state_u8(&config, 107), pre_state_config_lane_count);
    }

    if _result.is_ok() {
        assert_eq!(
            read_token_amount(&source_inventory),
            pre_transfer_0_from - (amount as u64)
        );
        assert_eq!(
            read_token_amount(&destination_inventory),
            pre_transfer_0_to + (amount as u64)
        );
    }

    // Spec ensures (reference). Kani's automatic checks cover
    // arithmetic UB; add explicit assertions below for cross-field
    // invariants (read post-state via read_token_amount(&<acct>)).
    //   ensures post.admin_key == pre.admin_key
    //   ensures post.max_fee_bps == pre.max_fee_bps
    //   ensures post.lane_count == pre.lane_count
}

